const d = $input.first().json;
const token = d.token;
const store_id = d.store_id;
const overall_rating = d.overall_rating;
const title = (d.title||'').replace(/'/g,"''");
const comment = (d.comment||'').replace(/'/g,"''");
const pros = (d.pros||'').replace(/'/g,"''");
const cons = (d.cons||'').replace(/'/g,"''");
const would_recommend = d.would_recommend ? 'true' : 'false';
return [{ json: { token, store_id, overall_rating, title, comment, pros, cons, would_recommend, insert_query: `INSERT INTO reviews (store_id, review_request_id, customer_id, product_id, order_id, overall_rating, title, comment, pros, cons, would_recommend, status, created_at) SELECT ${store_id}, rr.id, rr.customer_id, NULL, rr.order_id, ${overall_rating}, '${title}', '${comment}', '${pros}', '${cons}', ${would_recommend}, 'PENDING_MODERATION', NOW() FROM review_requests rr WHERE rr.token = '${token}'`, select_query: `SELECT id, overall_rating, comment FROM reviews WHERE review_request_id = (SELECT id FROM review_requests WHERE token = '${token}') ORDER BY id DESC LIMIT 1` } }];

const review = $('Get Review').first().json;
if (!review || !review.id) throw new Error('Review not saved — got: ' + JSON.stringify(review));
const summary = ($input.first().json?.response || 'Resume indisponible').substring(0,200).replace(/'/g,"''");
const r = Number(review.overall_rating) || 3;
let route, sentiment, status_update, sav_triggered, alert_sql;
if (r <= 2) {
  route = 'sav'; sentiment = 'negative'; status_update = ''; sav_triggered = true;
  alert_sql = `INSERT INTO alerts (store_id,type,severity,message,is_read,is_sent,created_at) VALUES (1,'BAD_REVIEW','high','Avis negatif ${r}/5',false,false,NOW());`;
} else if (r >= 4) {
  route = 'publish'; sentiment = 'positive'; status_update = "status='PUBLISHED', moderated_at=NOW(),"; sav_triggered = false;
  alert_sql = '';
} else {
  route = 'moderate'; sentiment = 'neutral'; status_update = ''; sav_triggered = false;
  alert_sql = '';
}
const update_sql = `UPDATE reviews SET ${status_update} ai_summary='${summary}', ai_sentiment='${sentiment}', sav_triggered=${sav_triggered} WHERE id=${review.id}; ${alert_sql}`;
return [{ json: { reviewId: review.id, rating: r, route, summary, update_sql } }];
